@[elab_as_elim, cases_eliminator]
def _root_.WithLp.rec {V} {p} (motive : WithLp p V → Sort*)
    (toLp : ∀ v, motive ((WithLp.equiv p _).symm v)) : ∀ v, motive v

lemma wave_dt {s : Space d} {f₀' : ℝ → ℝ →L[ℝ] EuclideanSpace ℝ (Fin d)}
    (h' : ∀ x, HasFDerivAt f₀ (f₀' x) x) :
    ∂ₜ (fun t => f₀ (inner ℝ x s - c * t)) = fun t => -c • (f₀' (inner ℝ x s - c * t)) 1

lemma wave_dt2 {s : Space d} {f₀' : ℝ → ℝ →L[ℝ] EuclideanSpace ℝ (Fin d)}
    {f₀'' : ℝ → ℝ →L[ℝ] EuclideanSpace ℝ (Fin d)}
    (h'' : ∀ x, HasFDerivAt (fun x' => f₀' x' 1) (f₀'' x) x) :
    ∂ₜ (fun t => -c • (f₀' (inner ℝ x s - c * t)) 1) t
    =
    c^2 • (f₀'' (inner ℝ x s - c * t)) 1

lemma time_differentiable_of_eq_planewave {s : Space} {hs : inner ℝ s s = 1}
    {f₀ : ℝ → EuclideanSpace ℝ (Fin 3)} {f : Time → Space → EuclideanSpace ℝ (Fin 3)}
    (h' : Differentiable ℝ f₀) (hf : f = planeWave f₀ c s hs) :
    Differentiable ℝ fun t => f t x

lemma crossProduct_time_differentiable_of_right_eq_planewave {s : Space} {hs : inner ℝ s s = 1}
    {f₀ : ℝ → EuclideanSpace ℝ (Fin 3)} {f : Time → Space → EuclideanSpace ℝ (Fin 3)}
    (h' : Differentiable ℝ f₀) (hf : f = planeWave f₀ c s hs) :
    DifferentiableAt ℝ (fun t => s ⨯ₑ₃ (f t x)) t

lemma crossProduct_differentiable_of_right_eq_planewave {s : Space}
    {f₀ : ℝ → EuclideanSpace ℝ (Fin 3)} (h' : Differentiable ℝ f₀) :
    DifferentiableAt ℝ (fun u => s ⨯ₑ₃ (f₀ u)) u

lemma differentiable_uncurry_of_eq_planewave {s : Space} {hs : inner ℝ s s = 1}
    {f₀ : ℝ → EuclideanSpace ℝ (Fin 3)} (hf : f = planeWave f₀ c s hs)
    (h' : Differentiable ℝ f₀) : Differentiable ℝ ↿f

lemma transverse_upto_time_fun_of_eq_electricPlaneWave {E₀ : ℝ → EuclideanSpace ℝ (Fin 3)}
    {s : Space} {hs : inner ℝ s s = 1} {E : ElectricField}
    {B : MagneticField} (hEwave : E = electricPlaneWave E₀ c s hs)
    (h' : Differentiable ℝ E₀) (hm : OM.FreeMaxwellEquations E B) :
    ∃ (c : Time → EuclideanSpace ℝ (Fin 3)), ∀ t x, inner ℝ (E t x) s = inner ℝ (c t) s

lemma transverse_upto_time_fun_of_eq_magneticPlaneWave {B₀ : ℝ → EuclideanSpace ℝ (Fin 3)}
    {s : Space} {hs : inner ℝ s s = 1} {E : ElectricField}
    {B : MagneticField} (hBwave : B = magneticPlaneWave B₀ c s hs)
    (h' : Differentiable ℝ B₀) (hm : OM.FreeMaxwellEquations E B) :
    ∃ (c : Time → EuclideanSpace ℝ (Fin 3)), ∀ t x, inner ℝ (B t x) s = inner ℝ (c t) s

lemma time_deriv_electricPlaneWave_eq_cross_time_deriv_magneticPlaneWave
    {t : Time} {x : Space} {B₀ : ℝ → EuclideanSpace ℝ (Fin 3)}
    {s : Space} {hs : inner ℝ s s = 1} {E : ElectricField} {B : MagneticField}
    (hc : c = (√(μ • ε))⁻¹) (hBwave : B = magneticPlaneWave B₀ c s hs)
    (h' : Differentiable ℝ B₀) (hm : OM.FreeMaxwellEquations E B) :
    ∂ₜ (fun t => E t x) t = - (√(μ • ε))⁻¹ • (s ⨯ₑ₃ (∂ₜ (fun t => B t x) t))

lemma time_deriv_magneticPlaneWave_eq_cross_time_deriv_electricPlaneWave
    {t : Time} {x : Space} {E₀ : ℝ → EuclideanSpace ℝ (Fin 3)}
    {s : Space} {hs : inner ℝ s s = 1} {E : ElectricField} {B : MagneticField}
    (hc : c = (√(μ • ε))⁻¹) (hEwave : E = electricPlaneWave E₀ c s hs)
    (h' : Differentiable ℝ E₀) (hm : OM.FreeMaxwellEquations E B) :
    ∂ₜ (fun t => B t x) t = (√(μ • ε)) • (s ⨯ₑ₃ (∂ₜ (fun t => E t x) t))

@[simp]
lemma powerset_of_empty :
    powerset ∅ = {∅}

lemma insert_Q5_mem_minimalSuperSet {S5 S10 : Finset ℤ} {x : Charges}
    (z : ℤ) (hz : z ∈ S5) (hznot : z ∉ x.2.2.1) :
    (x.1, x.2.1, insert z x.2.2.1, x.2.2.2) ∈ minimalSuperSet S5 S10 x

lemma insert_Q10_mem_minimalSuperSet {S5 S10 : Finset ℤ} {x : Charges}
    (z : ℤ) (hz : z ∈ S10) (hznot : z ∉ x.2.2.2) :
    (x.1, x.2.1, x.2.2.1, insert z x.2.2.2) ∈ minimalSuperSet S5 S10 x

lemma some_qHd_mem_minimalSuperSet_of_none {S5 S10 : Finset ℤ} {x2 : Option ℤ × Finset ℤ × Finset ℤ}
    (z : ℤ) (hz : z ∈ S5) :
    (some z, x2) ∈ minimalSuperSet S5 S10 (none, x2)

lemma some_qHu_mem_minimalSuperSet_of_none {S5 S10 : Finset ℤ}
    {x1 : Option ℤ} {x2 : Finset ℤ × Finset ℤ} (z : ℤ) (hz : z ∈ S5) :
    (x1, some z, x2) ∈ minimalSuperSet S5 S10 (x1, none, x2)

lemma exists_minimalSuperSet (S5 S10 : Finset ℤ) {x y : Charges}
    (hy : y ∈ ofFinset S5 S10) (hsubset : x ⊆ y)
    (hxneqy : x ≠ y) : ∃ z ∈ minimalSuperSet S5 S10 x, z ⊆ y

lemma completions_eq_singleton_of_complete {S5 S10 : Finset ℤ} (x : Charges)
    (hcomplete : IsComplete x) :
    completions S5 S10 x = {x}

lemma fiveChargeMultisetToList_count {I : CodimensionOneConfig} {S : Multiset ℤ} {a : ℤ}
    (hmem : a ∈ I.allowedBarFiveCharges) :
    (fiveChargeMultisetToList I S).count a = S.count a

lemma tenChargeMultisetToList_count {I : CodimensionOneConfig} {S : Multiset ℤ} {a : ℤ}
    (hmem : a ∈ I.allowedTenCharges) :
    (tenChargeMultisetToList I S).count a = S.count a

lemma Q5_mem_powerset_filter_card {n : ℕ}
    (hcard : 𝓜.quantaBarFiveMatter.card = n) : 𝓜.Q5.toFinset ∈
      I.allowedBarFiveCharges.powerset.filter fun x => x.card = n

@[simp]
lemma powerset_of_empty {T : PotentialTerm} :
    powerset (∅ : T.ChargeProfile) = {∅}

lemma mem_irreducibleElems'_of_irreducible {I : CodimensionOneConfig} {T : PotentialTerm}
    (x : ChargeProfile T) (h : IsIrreducible x) (hx : x ∈ finsetOfCodimensionOneConfig I T) :
    x ∈ irreducibleElems' I T

lemma isIrreducible_iff_mem_irreducibleElems {I : CodimensionOneConfig} {T : PotentialTerm}
    (x : ChargeProfile T) (hx : x ∈ finsetOfCodimensionOneConfig I T) :
    IsIrreducible x ↔ x ∈ irreducibleElems I T
